    "skill_id" INTEGER GENERATED BY DEFAULT AS IDENTITY (START WITH 1000),
    "skill_name" VARCHAR(255) NOT NULL,
    CONSTRAINT "skill_pkey" PRIMARY KEY ("skill_id")
